import { useState, useCallback } from "react";
import axios from "axios";

const API_BASE_URL = "http://localhost:5000/api/auth";

const useAuth = () => {
    const [isLogin, setIsLogin] = useState(true);
    const [formData, setFormData] = useState({
        matricula: "",
        correo: "",
        password: "",
        confirmPassword: "",
        // CAMBIO 1: Renombramos 'recoveryEmail' a 'recoveryInput'
        recoveryInput: "",
    });
    const [errors, setErrors] = useState({});
    const [message, setMessage] = useState("");
    const [showTemporaryBlock, setShowTemporaryBlock] = useState(false);
    const [showRecovery, setShowRecovery] = useState(false);
    const [recoverySuccess, setRecoverySuccess] = useState(false);
    const [isLoading, setIsLoading] = useState(false);

    // --- Funciones de Validación ---
    const validateEmail = (email) => {
        const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return re.test(email);
    };

    const validatePassword = (password) => {
        const hasUpperCase = /[A-Z]/.test(password);
        const hasNumber = /\d/.test(password);
        const hasSpecialChar = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(
            password
        );
        return password.length >= 8 && hasUpperCase && hasNumber && hasSpecialChar;
    };

    // --- Handlers de Estado (handleChange se mantiene) ---
    const handleChange = useCallback((e) => {
        const { name, value } = e.target;
        setFormData((prev) => ({
            ...prev,
            [name]: value,
        }));
        setErrors((prev) => (prev[name] ? { ...prev, [name]: "" } : prev));
        setMessage("");
    }, []);

    const toggleMode = useCallback(() => {
        setIsLogin((prev) => !prev);
        setFormData({
            matricula: "",
            correo: "",
            password: "",
            confirmPassword: "",
            // CAMBIO 2: Asegurar que el nuevo campo se resetea
            recoveryInput: "",
        });
        setErrors({});
        setShowTemporaryBlock(false);
        setMessage("");
    }, []);

    const handleBackToLogin = useCallback(() => {
        setShowRecovery(false);
        setRecoverySuccess(false);
        setErrors({});
        setMessage("");
    }, []);

    const handleRecoverPassword = useCallback(() => {
        setShowRecovery(true);
        // CAMBIO 3: Usamos el nuevo nombre del campo para resetearlo
        setFormData((prev) => ({ ...prev, recoveryInput: "" }));
        setErrors({});
        setRecoverySuccess(false);
        setMessage("");
    }, []);

    // --- Lógica de Auth (Conexión al Backend) ---

    const validateAndSubmit = useCallback(
        async (e) => {
            e.preventDefault();
            const newErrors = {};
            setMessage("");

            // 1. Validación Local (se mantiene la lógica)
            if (isLogin) {
                if (!formData.matricula)
                    newErrors.matricula = "La matrícula es requerida";
                if (!formData.password)
                    newErrors.password = "La contraseña es requerida";
            } else {
                if (!formData.matricula)
                    newErrors.matricula = "La matrícula es requerida";
                else if (formData.matricula.length < 5)
                    newErrors.matricula = "Matrícula no válida";
                if (!formData.correo) newErrors.correo = "El correo es requerido";
                else if (!validateEmail(formData.correo))
                    newErrors.correo = "Formato de correo electrónico no válido";
                if (!formData.password)
                    newErrors.password = "La contraseña es requerida";
                else if (!validatePassword(formData.password))
                    newErrors.password = "8+ caracteres, 1 Mayúscula, 1 Número, 1 Signo";
                if (formData.password !== formData.confirmPassword)
                    newErrors.confirmPassword = "Las contraseñas no coinciden";
            }

            if (Object.keys(newErrors).length > 0) {
                setErrors(newErrors);
                return;
            }

            setIsLoading(true);

            // 2. Llamada al Backend (se mantiene la lógica de login/registro)
            try {
                const url = isLogin
                    ? `${API_BASE_URL}/login`
                    : `${API_BASE_URL}/register`;
                let payload = isLogin
                    ? { matricula: formData.matricula, password: formData.password }
                    : {
                        matricula: formData.matricula,
                        correo: formData.correo,
                        password: formData.password,
                    };

                const response = await axios.post(url, payload);

                if (isLogin) {
                    localStorage.setItem("userToken", response.data.token);
                    setMessage("¡Inicio de sesión exitoso! Redirigiendo...");
                    // Aquí va la redirección
                } else {
                    setMessage("Registro exitoso. Puedes iniciar sesión.");
                    toggleMode();
                }
            } catch (error) {
                const backendMessage = error.response?.data?.message;
                if (
                    error.response?.status === 403 &&
                    backendMessage?.includes("bloqueada")
                ) {
                    setShowTemporaryBlock(true);
                    setTimeout(() => setShowTemporaryBlock(false), 5000);
                } else if (backendMessage) {
                    setMessage(`Error: ${backendMessage}`);
                } else {
                    setMessage("Error de conexión con el servidor. Inténtalo más tarde.");
                }
            } finally {
                setIsLoading(false);
            }
        },
        [isLogin, formData, toggleMode]
    );

    // LÓGICA DE RECUPERACIÓN MODIFICADA
    const submitRecovery = useCallback(
        async (e) => {
            e.preventDefault();
            const newErrors = {};
            setMessage("");

            // CAMBIO 4: Validamos que el campo 'recoveryInput' no esté vacío
            if (!formData.recoveryInput)
                newErrors.recoveryInput = "La matrícula o el correo son requeridos";
            // NOTA: Quitamos la validación de formato de email, ya que puede ser una matrícula

            if (Object.keys(newErrors).length > 0) {
                setErrors(newErrors);
                return;
            }

            setIsLoading(true);

            try {
                // CAMBIO 5: Enviamos el valor de 'recoveryInput' con la misma clave al backend.
                await axios.post(`${API_BASE_URL}/forgot-password`, {
                    recoveryInput: formData.recoveryInput,
                });

                setRecoverySuccess(true);
            } catch (error) {
                const backendMessage = error.response?.data?.message;
                if (error.response?.status === 404) {
                    // CAMBIO 6: El mensaje de error ahora aplica al campo 'recoveryInput'
                    setErrors({
                        recoveryInput:
                            "El identificador (matrícula o correo) no está registrado en el sistema",
                    });
                } else if (backendMessage) {
                    setMessage(`Error: ${backendMessage}`);
                } else {
                    setMessage("Error de conexión. No se pudo enviar el correo.");
                }
            } finally {
                setIsLoading(false);
            }
        },
        [formData]
    );

    return {
        // Estados
        isLogin,
        formData,
        errors,
        message,
        showTemporaryBlock,
        showRecovery,
        recoverySuccess,
        isLoading,
        // Handlers
        handleChange,
        toggleMode,
        handleRecoverPassword,
        handleBackToLogin,
        handleSubmit: validateAndSubmit,
        handleRecoverySubmit: submitRecovery,
    };
};

export default useAuth;
